package com.shale.data.dao;

import static org.junit.jupiter.api.Assertions.*;
import java.nio.file.*;
import org.junit.jupiter.api.Test;

class UserReleaseStateMigrationContractTest {
	private static String read(String p)throws Exception{Path x=Path.of(p);if(!Files.exists(x))x=Path.of("..").resolve(p);return Files.readString(x).replace("\r\n","\n");}
	@Test void strictTenantOwnedShapeVocabularyAndScopeAreClosed()throws Exception{String s=read("docs/sql/2026-09-28_user_release_state_foundation_phase3a.sql");assertTrue(s.contains("CREATE TABLE dbo.UserReleaseState("));assertTrue(s.contains("ShaleClientId int NOT NULL"));assertTrue(s.contains("UserId int NOT NULL"));assertTrue(s.contains("ApplicationReleaseId bigint NULL"));assertTrue(s.contains("ClientType IN('DESKTOP','WEB','MOBILE')"));assertTrue(s.contains("ReleaseChannel IN('PRODUCTION','PILOT','DEVELOPMENT')"));assertTrue(s.contains("UX_UserReleaseState_Scope ON dbo.UserReleaseState(ShaleClientId,UserId,ClientType,ReleaseChannel)"));assertTrue(s.contains("RowVer rowversion NOT NULL"));assertFalse(s.contains("INSERT dbo.UserReleaseState"));}
	@Test void trustedNonCascadingTenantUserAndReleaseRelationshipsAreRequired()throws Exception{String s=read("docs/sql/2026-09-28_user_release_state_foundation_phase3a.sql");assertTrue(s.contains("FOREIGN KEY(ShaleClientId,UserId) REFERENCES dbo.Users(ShaleClientId,Id) ON DELETE NO ACTION"));assertTrue(s.contains("FOREIGN KEY(ApplicationReleaseId) REFERENCES dbo.ApplicationReleases(Id) ON DELETE NO ACTION"));assertTrue(s.contains("is_not_trusted=1 OR delete_referential_action<>0"));}
	@Test void tenantFilterProvidesReadAndWriteDefenseWithoutOverlay()throws Exception{String s=read("docs/sql/2026-09-28_user_release_state_foundation_phase3a.sql");assertTrue(s.contains("ADD FILTER PREDICATE sec.fn_FilterByTenant(ShaleClientId)"));assertTrue(s.contains("ADD BLOCK PREDICATE sec.fn_FilterByTenant(ShaleClientId)")&&s.contains("AFTER INSERT")&&s.contains("AFTER UPDATE"));assertFalse(s.contains("fn_FilterByTenantOrGlobal"));}
	@Test void migrationIsTransactionalRerunnableAndContainsNoLaterPhaseRuntime()throws Exception{String s=read("docs/sql/2026-09-28_user_release_state_foundation_phase3a.sql");assertTrue(s.contains("SET XACT_ABORT ON;")&&s.contains("BEGIN TRANSACTION;")&&s.contains("ROLLBACK TRANSACTION"));assertTrue(s.contains("IF OBJECT_ID(N'dbo.UserReleaseState',N'U') IS NULL"));assertTrue(s.contains("IF NOT EXISTS(SELECT 1 FROM sys.indexes"));for(String forbidden:new String[]{"ApplicationInstances","UserSessions","Heartbeat","PubSub","Geolocation","ApplicationUpdateAttempts"})assertFalse(s.contains(forbidden));}
	@Test void verifierIsReadOnlyCollationSafeAndProtectsEarlierPhases()throws Exception{String s=read("docs/sql/verification/2026-09-28_user_release_state_foundation_phase3a_verification.sql");for(String finding:new String[]{"missing UserReleaseState table","missing or incompatible exact columns","missing primary key","missing, disabled, untrusted, or cascading foreign keys","missing logical scope uniqueness","missing release lookup index","missing client type vocabulary","missing strict TenantFilter predicates","unexpected overlay predicate","unexpected seed rows","Phase 1A or 1B regression"})assertTrue(s.contains(finding),finding);assertTrue(s.contains("COLLATE DATABASE_DEFAULT"));assertTrue(s.contains("IF EXISTS(SELECT 1 FROM @Findings WHERE FindingCount<>0)"));assertFalse(s.contains("CREATE TABLE"));assertFalse(s.contains("ALTER TABLE"));}
	@Test void liveRlsExerciseCoversTenantSevenTenantEightReadAndWriteDefense()throws Exception{String s=read("docs/sql/verification/2026-09-28_user_release_state_phase3a_rls.sql");assertTrue(s.contains("@value=7")&&s.contains("@value=8"));assertTrue(s.contains("Same-tenant insert/read failed"));assertTrue(s.contains("Tenant 7 cross-tenant insert unexpectedly succeeded"));assertTrue(s.contains("Tenant 8 read tenant 7 state"));assertTrue(s.contains("ROLLBACK TRANSACTION"));}
}
